load_one_sample <- function(path) {
  sample_name <- tools::file_path_sans_ext(basename(path))
  if (dir.exists(path)) {
    if (file.exists(file.path(path, "filtered_feature_bc_matrix", "matrix.mtx")) ||
        file.exists(file.path(path, "filtered_feature_bc_matrix", "matrix.mtx.gz"))) {
      counts <- Read10X(data.dir = file.path(path, "filtered_feature_bc_matrix"))
    } else {
      counts <- Read10X(data.dir = path)
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = sample_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (grepl("\\.(h5|hdf5)$", path, ignore.case = TRUE)) {
    counts <- Read10X_h5(filename = path)
    if (is.list(counts)) {
      counts <- counts[[1]]
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = sample_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (grepl("\\.rds$", path, ignore.case = TRUE)) {
    obj <- readRDS(path)
    if (inherits(obj, "Seurat")) {
      seu <- obj
      sample_name <- if ("orig.ident" %in% colnames(seu[[]])) {
        unique(as.character(seu$orig.ident))[1]
      } else {
        sample_name
      }
    } else {
      counts <- obj
      rownames(counts) <- make.unique(as.character(rownames(counts)))
      seu <- CreateSeuratObject(
        counts = counts,
        project = sample_name,
        min.cells = min_cells,
        min.features = min_features
      )
    }
  } else {
    stop("Unsupported input: ", path)
  }
  seu$sample_id <- sample_name
  seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)
  seu <- RenameCells(seu, add.cell.id = sample_name)
  seu
}

