is_10x_dir <- function(path) {
  file.exists(file.path(path, "matrix.mtx")) || file.exists(file.path(path, "matrix.mtx.gz"))
}

is_10x_h5 <- function(path) {
  grepl("\\.h5$", path, ignore.case = TRUE)
}

read_count_matrix <- function(path) {
  if (dir.exists(path) && is_10x_dir(path)) {
    counts <- Read10X(data.dir = path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(counts)
  }

  if (file.exists(path) && is_10x_h5(path)) {
    counts <- Read10X_h5(filename = path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(counts)
  }

  if (file.exists(path) && grepl("\\.rds$", path, ignore.case = TRUE)) {
    obj <- readRDS(path)
    if (inherits(obj, "Seurat")) {
      return(obj)
    }
    if (inherits(obj, "dgCMatrix") || inherits(obj, "matrix") || inherits(obj, "data.frame")) {
      mat <- as.matrix(obj)
      rownames(mat) <- make.unique(as.character(rownames(mat)))
      return(Matrix(mat, sparse = TRUE))
    }
    stop("RDS input must contain a Seurat object or a gene-by-cell count matrix.")
  }

  if (file.exists(path)) {
    mat <- read.delim(path, header = TRUE, row.names = 1, check.names = FALSE, stringsAsFactors = FALSE)
    rownames(mat) <- make.unique(as.character(rownames(mat)))
    return(Matrix(as.matrix(mat), sparse = TRUE))
  }

  stop("No valid input found. Provide a 10X directory, 10X H5 file, RDS object/matrix, or tab-delimited count matrix.")
}

