library(Seurat)
library(ggplot2)
library(Matrix)

set.seed(42)

input_type <- "auto"
data_path <- "."
project_name <- "PBMC"
output_dir <- "pbmc_seurat_results"

min_cells <- 3
min_features <- 200
min_feat <- 200
max_feat <- 6000
max_mt <- 10
n_variable <- 2000
n_pcs <- 30
resolution <- 0.6
doublet_rate <- 0.07
pK_fixed <- 0.01
run_pk_sweep <- FALSE

dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)

load_pbmc_data <- function(input_type = "auto", data_path = ".") {
  if (input_type == "auto") {
    if (file.exists(file.path(data_path, "outs", "filtered_feature_bc_matrix.h5"))) {
      input_type <- "h5"
      data_path <- file.path(data_path, "outs", "filtered_feature_bc_matrix.h5")
    } else if (file.exists(file.path(data_path, "filtered_feature_bc_matrix.h5"))) {
      input_type <- "h5"
      data_path <- file.path(data_path, "filtered_feature_bc_matrix.h5")
    } else if (dir.exists(file.path(data_path, "outs", "filtered_feature_bc_matrix"))) {
      input_type <- "mtx"
      data_path <- file.path(data_path, "outs", "filtered_feature_bc_matrix")
    } else if (dir.exists(file.path(data_path, "filtered_feature_bc_matrix"))) {
      input_type <- "mtx"
      data_path <- file.path(data_path, "filtered_feature_bc_matrix")
    } else if (
      file.exists(file.path(data_path, "matrix.mtx")) ||
        file.exists(file.path(data_path, "matrix.mtx.gz"))
    ) {
      input_type <- "mtx"
    } else {
      h5_files <- list.files(data_path, pattern = "\\.h5$", full.names = TRUE)
      rds_files <- list.files(data_path, pattern = "\\.rds$", full.names = TRUE)
      if (length(h5_files) == 1) {
        input_type <- "h5"
        data_path <- h5_files[1]
      } else if (length(rds_files) == 1) {
        input_type <- "rds"
        data_path <- rds_files[1]
      } else {
        stop("No supported input found. Put a 10X matrix folder, filtered_feature_bc_matrix.h5, or one .rds file in the working directory, or set input_type/data_path.")
      }
    }
  }

  if (input_type == "mtx") {
    counts <- Read10X(data.dir = data_path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (input_type == "h5") {
    counts <- Read10X_h5(filename = data_path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (input_type == "rds") {
    seu <- readRDS(data_path)
    if (!inherits(seu, "Seurat")) {
      seu <- CreateSeuratObject(
        counts = seu,
        project = project_name,
        min.cells = min_cells,
        min.features = min_features
      )
    }
  } else if (input_type == "matrix") {
    exp_mat <- read.table(data_path, header = TRUE, row.names = 1, sep = "\t", check.names = FALSE)
    rownames(exp_mat) <- make.unique(rownames(exp_mat))
    seu <- CreateSeuratObject(
      counts = Matrix(as.matrix(exp_mat), sparse = TRUE),
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else {
    stop("input_type must be one of: auto, mtx, h5, rds, matrix")
  }

  seu
}

run_processing <- function(seu, n_variable = 2000, n_pcs = 30, resolution = 0.6) {
  DefaultAssay(seu) <- if ("RNA" %in% names(seu@assays)) "RNA" else DefaultAssay(seu)

  seu <- NormalizeData(seu, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)

  s_genes <- intersect(Seurat::cc.genes$s.genes, rownames(seu))
  g2m_genes <- intersect(Seurat::cc.genes$g2m.genes, rownames(seu))
  if (length(s_genes) >= 5 && length(g2m_genes) >= 5) {
    seu <- CellCycleScoring(
      seu,
      s.features = s_genes,
      g2m.features = g2m_genes,
      set.ident = FALSE
    )
  }

  seu <- FindVariableFeatures(
    seu,
    selection.method = "vst",
    nfeatures = min(n_variable, nrow(seu)),
    verbose = FALSE
  )

  regress_vars <- intersect(c("percent.mt", "S.Score", "G2M.Score"), colnames(seu@meta.data))
  if (length(regress_vars) > 0) {
    seu <- ScaleData(seu, vars.to.regress = regress_vars, verbose = FALSE)
  } else {
    seu <- ScaleData(seu, verbose = FALSE)
  }

  n_pcs_use <- min(n_pcs, ncol(seu) - 1, length(VariableFeatures(seu)) - 1)
  if (n_pcs_use < 2) {
    stop("Too few cells or variable features for PCA.")
  }

  seu <- RunPCA(seu, npcs = n_pcs_use, verbose = FALSE)
  seu <- FindNeighbors(seu, dims = 1:n_pcs_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = resolution, verbose = FALSE)
  seu <- RunUMAP(seu, dims = 1:n_pcs_use, verbose = FALSE)

  list(object = seu, n_pcs_use = n_pcs_use)
}

run_doubletfinder_safe <- function(seu, n_pcs = 10, doublet_rate = 0.07, pK = 0.01, run_pk_sweep = FALSE) {
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) {
    message("DoubletFinder not installed. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  if (!"seurat_clusters" %in% colnames(seu@meta.data)) {
    message("No seurat_clusters found. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  if (isTRUE(run_pk_sweep)) {
    sweep.res <- DoubletFinder::paramSweep(seu, PCs = 1:n_pcs, sct = FALSE)
    sweep.stats <- DoubletFinder::summarizeSweep(sweep.res, GT = FALSE)
    bcmvn <- DoubletFinder::find.pK(sweep.stats)
    pK <- as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
  }

  annotations <- as.character(seu$seurat_clusters)
  homotypic_prop <- tryCatch(
    DoubletFinder::modelHomotypic(annotations),
    error = function(e) 0
  )

  n_exp <- round(doublet_rate * ncol(seu))
  n_exp_adj <- round(n_exp * (1 - homotypic_prop))

  seu_df <- tryCatch(
    DoubletFinder::doubletFinder(
      seu,
      PCs = 1:n_pcs,
      pN = 0.25,
      pK = as.numeric(pK),
      nExp = n_exp_adj,
      reuse.pANN = NULL,
      sct = FALSE
    ),
    error = function(e) {
      message("DoubletFinder failed. Marking all cells as Singlet.")
      seu$doublet_status <- "Singlet"
      return(seu)
    }
  )

  df_col <- grep("DF.classifications", colnames(seu_df@meta.data), value = TRUE)
  if (length(df_col) > 0) {
    seu_df$doublet_status <- as.character(seu_df@meta.data[[df_col[1]]])
  } else {
    seu_df$doublet_status <- "Singlet"
  }

  seu_df
}

