is_10x_dir <- function(d) {
  matrix_exists <- any(file.exists(file.path(d, c("matrix.mtx", "matrix.mtx.gz"))))
  barcode_exists <- any(file.exists(file.path(d, c("barcodes.tsv", "barcodes.tsv.gz"))))
  feature_exists <- any(file.exists(file.path(d, c("features.tsv", "features.tsv.gz", "genes.tsv", "genes.tsv.gz"))))
  matrix_exists && barcode_exists && feature_exists
}

