  if (is_10x_dir(".")) {
    data_dirs <- "."
  } else {
    subdirs <- list.dirs(".", recursive = FALSE, full.names = TRUE)
    data_dirs <- subdirs[vapply(subdirs, is_10x_dir, logical(1))]
    h5_files <- list.files(".", pattern = "\\.h5$", recursive = TRUE, full.names = TRUE)
    matrix_files <- list.files(".", pattern = "\\.(csv|tsv|txt)(\\.gz)?$", recursive = FALSE, full.names = TRUE)
    matrix_files <- matrix_files[!basename(matrix_files) %in% c("features.tsv", "features.tsv.gz", "genes.tsv", "genes.tsv.gz", "barcodes.tsv", "barcodes.tsv.gz")]
  }
}

