safe_sample_name <- function(x) {
  x <- gsub("^\\./", "", x)
  x <- gsub("/$", "", x)
  x <- basename(x)
  x <- gsub("[^A-Za-z0-9_\\-]+", "_", x)
  ifelse(nchar(x) == 0 || x == ".", project_name, x)
}

read_count_input <- function(path, input_type) {
  if (input_type == "mtx") {
    counts <- Read10X(data.dir = path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(counts)
  }
  if (input_type == "h5") {
    counts <- Read10X_h5(filename = path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(counts)
  }
  if (input_type == "matrix") {
    sep <- ifelse(grepl("\\.csv(\\.gz)?$", path, ignore.case = TRUE), ",", "\t")
    mat <- read.table(path, sep = sep, header = TRUE, row.names = 1, check.names = FALSE, stringsAsFactors = FALSE)
    rownames(mat) <- make.unique(rownames(mat))
    return(Matrix(as.matrix(mat), sparse = TRUE))
  }
  stop("Unsupported input_type")
}

