score_cell_cycle_safe <- function(seu) {
  s_genes <- intersect(Seurat::cc.genes$s.genes, rownames(seu))
  g2m_genes <- intersect(Seurat::cc.genes$g2m.genes, rownames(seu))
  if (length(s_genes) >= 5 && length(g2m_genes) >= 5) {
    seu <- CellCycleScoring(seu, s.features = s_genes, g2m.features = g2m_genes, set.ident = FALSE)
  } else {
    seu$S.Score <- 0
    seu$G2M.Score <- 0
    seu$Phase <- "Unknown"
  }
  seu
}

process_single <- function(seu, n_pcs = 30, resolution = 0.6, regress_vars = c("percent.mt")) {
  DefaultAssay(seu) <- "RNA"
  seu <- NormalizeData(seu, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)
  seu <- score_cell_cycle_safe(seu)
  seu <- FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable_features, verbose = FALSE)
  vars_to_regress <- intersect(regress_vars, colnames(seu@meta.data))
  seu <- ScaleData(seu, vars.to.regress = vars_to_regress, verbose = FALSE)
  npcs <- min(n_pcs, ncol(seu) - 1, length(VariableFeatures(seu)))
  npcs <- max(2, npcs)
  seu <- RunPCA(seu, npcs = npcs, verbose = FALSE)
  dims_use <- seq_len(min(npcs, n_pcs))
  seu <- FindNeighbors(seu, dims = dims_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = resolution, verbose = FALSE)
  seu <- RunUMAP(seu, dims = dims_use, verbose = FALSE)
  seu
}

process_integrated <- function(obj_list, n_pcs = 30, resolution = 0.6) {
  if (length(obj_list) == 1) {
    return(process_single(obj_list[[1]], n_pcs = n_pcs, resolution = resolution))
  }
  obj_list <- lapply(obj_list, function(x) {
    DefaultAssay(x) <- "RNA"
    x <- NormalizeData(x, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)
    x <- score_cell_cycle_safe(x)
    x <- FindVariableFeatures(x, selection.method = "vst", nfeatures = n_variable_features, verbose = FALSE)
    x
  })
  features <- SelectIntegrationFeatures(object.list = obj_list, nfeatures = n_variable_features)
  n_anchor_dims <- min(n_pcs, min(vapply(obj_list, ncol, integer(1))) - 1, length(features))
  n_anchor_dims <- max(2, n_anchor_dims)
  anchors <- FindIntegrationAnchors(object.list = obj_list, anchor.features = features, dims = seq_len(n_anchor_dims), verbose = FALSE)
  seu <- IntegrateData(anchorset = anchors, dims = seq_len(n_anchor_dims), verbose = FALSE)
  DefaultAssay(seu) <- "integrated"
  seu <- ScaleData(seu, verbose = FALSE)
  seu <- RunPCA(seu, npcs = n_anchor_dims, verbose = FALSE)
  dims_use <- seq_len(n_anchor_dims)
  seu <- FindNeighbors(seu, dims = dims_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = resolution, verbose = FALSE)
  seu <- RunUMAP(seu, dims = dims_use, verbose = FALSE)
  seu
}

