is_10x_dir <- function(path) {
  file.exists(file.path(path, "matrix.mtx")) || file.exists(file.path(path, "matrix.mtx.gz"))
}

has_10x_barcodes_features <- function(path) {
  barcodes_ok <- file.exists(file.path(path, "barcodes.tsv")) || file.exists(file.path(path, "barcodes.tsv.gz"))
  features_ok <- file.exists(file.path(path, "features.tsv")) || file.exists(file.path(path, "features.tsv.gz")) ||
    file.exists(file.path(path, "genes.tsv")) || file.exists(file.path(path, "genes.tsv.gz"))
  is_10x_dir(path) && barcodes_ok && features_ok
}

sample_id_from_path <- function(path) {
  path <- normalizePath(path, mustWork = FALSE)
  base <- basename(path)
  parent <- basename(dirname(path))
  grandparent <- basename(dirname(dirname(path)))
  if (base %in% c("filtered_feature_bc_matrix", "raw_feature_bc_matrix")) {
    return(parent)
  }
  if (base %in% c("outs") && parent != ".") {
    return(parent)
  }
  if (parent %in% c("outs")) {
    return(grandparent)
  }
  if (base %in% c(".", "")) {
    return(basename(getwd()))
  }
  tools::file_path_sans_ext(base)
}

discover_inputs <- function() {
  env_paths <- Sys.getenv("SCRNA_INPUT_PATHS", unset = "")
  if (nzchar(env_paths)) {
    paths <- trimws(unlist(strsplit(env_paths, ",")))
    return(data.frame(path = paths, sample_id = vapply(paths, sample_id_from_path, character(1)), stringsAsFactors = FALSE))
  }

  if (file.exists("sample_metadata.csv")) {
    md <- read.csv("sample_metadata.csv", stringsAsFactors = FALSE, check.names = FALSE)
    if (all(c("path", "sample_id") %in% colnames(md))) {
      return(md[, c("path", "sample_id"), drop = FALSE])
    }
  }

  tenx_paths <- character(0)
  if (has_10x_barcodes_features(".")) {
    tenx_paths <- c(tenx_paths, ".")
  }

  immediate_dirs <- list.dirs(".", full.names = TRUE, recursive = FALSE)
  for (d in immediate_dirs) {
    candidates <- unique(c(
      d,
      file.path(d, "filtered_feature_bc_matrix"),
      file.path(d, "raw_feature_bc_matrix"),
      file.path(d, "outs", "filtered_feature_bc_matrix"),
      file.path(d, "outs", "raw_feature_bc_matrix")
    ))
    candidates <- candidates[vapply(candidates, has_10x_barcodes_features, logical(1))]
    tenx_paths <- c(tenx_paths, candidates)
  }
  tenx_paths <- unique(normalizePath(tenx_paths, mustWork = FALSE))

  if (length(tenx_paths) > 0) {
    return(data.frame(path = tenx_paths, sample_id = vapply(tenx_paths, sample_id_from_path, character(1)), stringsAsFactors = FALSE))
  }

  h5_files <- list.files(".", pattern = "\\.h5$", full.names = TRUE, recursive = FALSE)
  if (length(h5_files) > 0) {
    return(data.frame(path = h5_files, sample_id = vapply(h5_files, sample_id_from_path, character(1)), stringsAsFactors = FALSE))
  }

  rds_files <- list.files(".", pattern = "\\.rds$", full.names = TRUE, recursive = FALSE)
  rds_files <- rds_files[!grepl("seurat_|pbmc_|processed|final|singlet|doublet", basename(rds_files), ignore.case = TRUE)]
  if (length(rds_files) > 0) {
    return(data.frame(path = rds_files, sample_id = vapply(rds_files, sample_id_from_path, character(1)), stringsAsFactors = FALSE))
  }

  count_files <- list.files(".", pattern = "counts|matrix|expression", full.names = TRUE, recursive = FALSE, ignore.case = TRUE)
  count_files <- count_files[grepl("\\.(csv|tsv|txt)(\\.gz)?$", count_files, ignore.case = TRUE)]
  count_files <- count_files[!grepl("metadata|markers|cluster|annotation", basename(count_files), ignore.case = TRUE)]
  if (length(count_files) > 0) {
    return(data.frame(path = count_files, sample_id = vapply(count_files, sample_id_from_path, character(1)), stringsAsFactors = FALSE))
  }

  stop("No input count matrices found. Put 10X matrix folders, .h5 files, .rds count matrices, or tabular count matrices in the working directory, or set SCRNA_INPUT_PATHS as comma-separated paths.")
}

select_expression_matrix <- function(x) {
  if (is.list(x) && !inherits(x, "dgCMatrix")) {
    if ("Gene Expression" %in% names(x)) {
      return(x[["Gene Expression"]])
    }
    if ("RNA" %in% names(x)) {
      return(x[["RNA"]])
    }
    return(x[[1]])
  }
  x
}

read_tabular_counts <- function(path) {
  sep <- if (grepl("\\.csv(\\.gz)?$", path, ignore.case = TRUE)) "," else "\t"
  mat_df <- read.table(path, header = TRUE, row.names = 1, sep = sep, check.names = FALSE, stringsAsFactors = FALSE)
  mat <- as.matrix(mat_df)
  rownames(mat) <- make.unique(as.character(rownames(mat)))
  Matrix(mat, sparse = TRUE)
}

load_one_sample <- function(path, sample_id) {
  if (dir.exists(path)) {
    counts <- select_expression_matrix(Read10X(data.dir = path))
    seu <- CreateSeuratObject(counts = counts, project = sample_id, min.cells = min_cells, min.features = min_features_create)
  } else if (grepl("\\.h5$", path, ignore.case = TRUE)) {
    counts <- select_expression_matrix(Read10X_h5(filename = path))
    seu <- CreateSeuratObject(counts = counts, project = sample_id, min.cells = min_cells, min.features = min_features_create)
  } else if (grepl("\\.rds$", path, ignore.case = TRUE)) {
    obj <- readRDS(path)
    if (inherits(obj, "Seurat")) {
      seu <- obj
    } else {
      counts <- select_expression_matrix(obj)
      if (!is.null(rownames(counts))) {
        rownames(counts) <- make.unique(as.character(rownames(counts)))
      }
      seu <- CreateSeuratObject(counts = counts, project = sample_id, min.cells = min_cells, min.features = min_features_create)
    }
  } else if (grepl("\\.(csv|tsv|txt)(\\.gz)?$", path, ignore.case = TRUE)) {
    counts <- read_tabular_counts(path)
    seu <- CreateSeuratObject(counts = counts, project = sample_id, min.cells = min_cells, min.features = min_features_create)
  } else {
    stop("Unsupported input format: ", path)
  }

  seu$sample_id <- sample_id
  seu$input_path <- path
  seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)
  seu[["percent.ribo"]] <- PercentageFeatureSet(seu, pattern = ribo_pattern)
  seu
}

