preprocess_cluster <- function(seu, n_variable_features = 2000, n_pcs = 30, resolution = 0.5, use_harmony_if_available = TRUE) {
  DefaultAssay(seu) <- "RNA"
  if (inherits(seu[["RNA"]], "Assay5")) {
    seu[["RNA"]] <- JoinLayers(seu[["RNA"]])
  }

  seu <- NormalizeData(seu, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)

  if (isTRUE(run_cell_cycle_scoring)) {
    s_genes <- intersect(Seurat::cc.genes$s.genes, rownames(seu))
    g2m_genes <- intersect(Seurat::cc.genes$g2m.genes, rownames(seu))
    if (length(s_genes) >= 5 && length(g2m_genes) >= 5) {
      seu <- CellCycleScoring(seu, s.features = s_genes, g2m.features = g2m_genes, set.ident = FALSE)
      seu$CC.Difference <- seu$S.Score - seu$G2M.Score
    }
  }

  seu <- FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable_features, verbose = FALSE)

  regress_vars <- vars_to_regress_default
  if (isTRUE(regress_cell_cycle) && "CC.Difference" %in% colnames(seu@meta.data)) {
    regress_vars <- c(regress_vars, "CC.Difference")
  }
  regress_vars <- intersect(regress_vars, colnames(seu@meta.data))

  seu <- ScaleData(seu, vars.to.regress = regress_vars, verbose = FALSE)

  n_pcs_use <- min(n_pcs, ncol(seu) - 1, length(VariableFeatures(seu)))
  if (n_pcs_use < 2) {
    stop("Too few cells or variable features for PCA.")
  }

  seu <- RunPCA(seu, npcs = n_pcs_use, verbose = FALSE)

  reduction_use <- "pca"
  if (isTRUE(use_harmony_if_available) && length(unique(seu$sample_id)) > 1 && requireNamespace("harmony", quietly = TRUE)) {
    suppressPackageStartupMessages(library(harmony))
    seu <- tryCatch(
      {
        RunHarmony(seu, group.by.vars = "sample_id", reduction.use = "pca", dims.use = 1:n_pcs_use, verbose = FALSE)
      },
      error = function(e) {
        message("Harmony failed; continuing with PCA: ", e$message)
        seu
      }
    )
    if ("harmony" %in% names(seu@reductions)) {
      reduction_use <- "harmony"
    }
  }

  seu <- FindNeighbors(seu, reduction = reduction_use, dims = 1:n_pcs_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = resolution, verbose = FALSE)
  seu <- RunUMAP(seu, reduction = reduction_use, dims = 1:n_pcs_use, verbose = FALSE)

  seu@misc$n_pcs_used <- n_pcs_use
  seu@misc$clustering_reduction <- reduction_use
  seu
}

