detect_input_type <- function(data_path) {
  if (file.exists(data_path) && grepl("\\.rds$", data_path, ignore.case = TRUE)) {
    return("rds")
  }
  if (file.exists(data_path) && grepl("\\.h5$", data_path, ignore.case = TRUE)) {
    return("h5")
  }
  if (dir.exists(data_path)) {
    h5_files <- list.files(data_path, pattern = "\\.h5$", full.names = TRUE)
    has_matrix <- file.exists(file.path(data_path, "matrix.mtx")) || file.exists(file.path(data_path, "matrix.mtx.gz"))
    has_barcodes <- file.exists(file.path(data_path, "barcodes.tsv")) || file.exists(file.path(data_path, "barcodes.tsv.gz"))
    has_features <- file.exists(file.path(data_path, "features.tsv")) || file.exists(file.path(data_path, "features.tsv.gz")) ||
      file.exists(file.path(data_path, "genes.tsv")) || file.exists(file.path(data_path, "genes.tsv.gz"))
    if (has_matrix && has_barcodes && has_features) {
      return("mtx")
    }
    if (length(h5_files) == 1) {
      return("h5_dir_single")
    }
  }
  if (file.exists(data_path) && grepl("\\.(txt|tsv|csv)(\\.gz)?$", data_path, ignore.case = TRUE)) {
    return("matrix")
  }
  stop("Could not automatically detect input format at data_path = ", data_path)
}

load_counts_or_seurat <- function(input_type, data_path, project_name, min_cells, min_features) {
  if (identical(input_type, "auto")) {
    input_type <- detect_input_type(data_path)
  }

  cat("Detected/input type:", input_type, "\n")

  if (identical(input_type, "mtx")) {
    counts <- Read10X(data.dir = data_path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (identical(input_type, "h5")) {
    counts <- Read10X_h5(filename = data_path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (identical(input_type, "h5_dir_single")) {
    h5_file <- list.files(data_path, pattern = "\\.h5$", full.names = TRUE)[1]
    counts <- Read10X_h5(filename = h5_file)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (identical(input_type, "rds")) {
    seu <- readRDS(data_path)
    if (!inherits(seu, "Seurat")) {
      stop("RDS input is not a Seurat object.")
    }
  } else if (identical(input_type, "matrix")) {
    sep <- if (grepl("\\.csv(\\.gz)?$", data_path, ignore.case = TRUE)) "," else "\t"
    exp_mat <- read.table(data_path, header = TRUE, row.names = 1, sep = sep, check.names = FALSE)
    rownames(exp_mat) <- make.unique(as.character(rownames(exp_mat)))
    counts <- Matrix::Matrix(as.matrix(exp_mat), sparse = TRUE)
    seu <- CreateSeuratObject(
      counts = counts,
      project = project_name,
      min.cells = min_cells,
      min.features = min_features
    )
  } else {
    stop("input_type must be one of: auto, mtx, h5, rds, matrix")
  }

  seu
}

run_standard_processing <- function(seu, n_variable_features, n_pcs, resolution, regress_vars = NULL) {
  DefaultAssay(seu) <- "RNA"
  seu <- NormalizeData(seu, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)
  seu <- FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable_features, verbose = FALSE)

  if (!is.null(regress_vars)) {
    regress_vars <- regress_vars[regress_vars %in% colnames(seu@meta.data)]
  }
  if (length(regress_vars) == 0) {
    regress_vars <- NULL
  }

  seu <- ScaleData(seu, vars.to.regress = regress_vars, verbose = FALSE)
  max_pcs <- min(n_pcs, ncol(seu) - 1, length(VariableFeatures(seu)))
  if (max_pcs < 2) {
    stop("Too few cells/features remaining to run PCA.")
  }
  seu <- RunPCA(seu, npcs = max_pcs, verbose = FALSE)
  dims_use <- seq_len(max_pcs)
  seu <- FindNeighbors(seu, dims = dims_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = resolution, verbose = FALSE)
  seu <- RunUMAP(seu, dims = dims_use, verbose = FALSE)
  seu
}

run_doubletfinder_safe <- function(seu, n_pcs = 30, doublet_rate = 0.075, pK = 0.01, run_pk_sweep = FALSE) {
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) {
    message("DoubletFinder not installed. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  if (!"seurat_clusters" %in% colnames(seu@meta.data)) {
    message("No seurat_clusters found. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  available_pcs <- if ("pca" %in% names(seu@reductions)) ncol(Embeddings(seu, "pca")) else 0
  n_pcs <- min(n_pcs, available_pcs)
  if (n_pcs < 2) {
    message("Insufficient PCA dimensions for DoubletFinder. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  if (isTRUE(run_pk_sweep)) {
    pK <- tryCatch({
      sweep.res <- DoubletFinder::paramSweep(seu, PCs = 1:n_pcs, sct = FALSE)
      sweep.stats <- DoubletFinder::summarizeSweep(sweep.res, GT = FALSE)
      bcmvn <- DoubletFinder::find.pK(sweep.stats)
      as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
    }, error = function(e) {
      message("DoubletFinder pK sweep failed: ", e$message)
      as.numeric(pK)
    })
  }

  annotations <- as.character(seu$seurat_clusters)
  homotypic_prop <- tryCatch(
    DoubletFinder::modelHomotypic(annotations),
    error = function(e) {
      message("modelHomotypic failed: ", e$message)
      0
    }
  )

  n_exp <- round(doublet_rate * ncol(seu))
  n_exp_adj <- round(n_exp * (1 - homotypic_prop))
  n_exp_adj <- max(1, n_exp_adj)

  cat("DoubletFinder expected doublets raw:", n_exp, "\n")
  cat("DoubletFinder expected doublets adjusted:", n_exp_adj, "\n")
  cat("DoubletFinder pK:", pK, "\n")

  seu_df <- tryCatch(
    DoubletFinder::doubletFinder(
      seu,
      PCs = 1:n_pcs,
      pN = 0.25,
      pK = as.numeric(pK),
      nExp = n_exp_adj,
      reuse.pANN = NULL,
      sct = FALSE
    ),
    error = function(e) {
      message("doubletFinder() failed: ", e$message)
      seu$doublet_status <- "Singlet"
      return(seu)
    }
  )

  df_col <- grep("DF.classifications", colnames(seu_df@meta.data), value = TRUE)
  df_col <- if (length(df_col) > 0) df_col[1] else NA_character_

  if (is.na(df_col)) {
    message("No DF.classifications column found. Marking all cells as Singlet.")
    seu_df$doublet_status <- "Singlet"
  } else {
    seu_df$doublet_status <- as.character(seu_df@meta.data[[df_col]])
  }

  seu_df
}

