annotate_pbmc_clusters <- function(seu, marker_sets) {
  DefaultAssay(seu) <- "RNA"
  seu <- join_layers_if_needed(seu, "RNA")

  avg <- AverageExpression(seu, assays = "RNA", layer = "data", group.by = "seurat_clusters", verbose = FALSE)$RNA
  marker_scores <- matrix(
    NA_real_,
    nrow = length(marker_sets),
    ncol = ncol(avg),
    dimnames = list(names(marker_sets), colnames(avg))
  )

  for (ct in names(marker_sets)) {
    genes <- intersect(marker_sets[[ct]], rownames(avg))
    if (length(genes) > 0) {
      marker_scores[ct, ] <- colMeans(avg[genes, , drop = FALSE])
    }
  }

  best <- apply(marker_scores, 2, function(x) {
    if (all(is.na(x))) {
      "Unassigned"
    } else {
      names(which.max(x))
    }
  })

  cluster_ids <- as.character(seu$seurat_clusters)
  seu$pbmc_celltype <- unname(best[cluster_ids])
  Idents(seu) <- "pbmc_celltype"

  list(seurat = seu, scores = marker_scores, cluster_annotation = data.frame(
    cluster = names(best),
    pbmc_celltype = unname(best),
    stringsAsFactors = FALSE
  ))
}

