safe_ggsave <- function(filename, plot, width = 8, height = 6, dpi = 300) {
  tryCatch(
    ggplot2::ggsave(filename = filename, plot = plot, width = width, height = height, dpi = dpi, limitsize = FALSE),
    error = function(e) message("Could not save plot ", filename, ": ", e$message)
  )
}

is_10x_dir <- function(path) {
  if (!dir.exists(path)) return(FALSE)
  has_matrix <- any(file.exists(file.path(path, c("matrix.mtx", "matrix.mtx.gz"))))
  has_barcodes <- any(file.exists(file.path(path, c("barcodes.tsv", "barcodes.tsv.gz"))))
  has_features <- any(file.exists(file.path(path, c("features.tsv", "features.tsv.gz", "genes.tsv", "genes.tsv.gz"))))
  has_matrix && has_barcodes && has_features
}

detect_input_type <- function(path) {
  if (dir.exists(path)) {
    h5_candidates <- list.files(path, pattern = "\\.h5$", full.names = TRUE)
    if (is_10x_dir(path)) return("mtx")
    if (length(h5_candidates) == 1) return("h5")
    if (file.exists(file.path(path, "filtered_feature_bc_matrix.h5"))) return("h5")
  }
  if (file.exists(path)) {
    ext <- tolower(tools::file_ext(path))
    if (ext == "h5") return("h5")
    if (ext == "rds") return("rds")
    if (ext %in% c("txt", "tsv", "csv")) return("matrix")
  }
  stop("Could not detect input type from input_path: ", path)
}

load_counts_as_seurat <- function(path, type, project, min_cells, min_features) {
  if (type == "auto") {
    type <- detect_input_type(path)
  }

  if (type == "mtx") {
    counts <- Read10X(data.dir = path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (type == "h5") {
    h5_path <- path
    if (dir.exists(path)) {
      if (file.exists(file.path(path, "filtered_feature_bc_matrix.h5"))) {
        h5_path <- file.path(path, "filtered_feature_bc_matrix.h5")
      } else {
        h5_files <- list.files(path, pattern = "\\.h5$", full.names = TRUE)
        if (length(h5_files) != 1) stop("Expected exactly one .h5 file in ", path, " but found ", length(h5_files))
        h5_path <- h5_files[[1]]
      }
    }
    counts <- Read10X_h5(filename = h5_path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    seu <- CreateSeuratObject(
      counts = counts,
      project = project,
      min.cells = min_cells,
      min.features = min_features
    )
  } else if (type == "rds") {
    seu <- readRDS(path)
    if (!inherits(seu, "Seurat")) stop("RDS file does not contain a Seurat object.")
  } else if (type == "matrix") {
    sep <- if (grepl("\\.csv$", tolower(path))) "," else "\t"
    exp_mat <- read.table(path, header = TRUE, sep = sep, row.names = 1, check.names = FALSE)
    rownames(exp_mat) <- make.unique(rownames(exp_mat))
    counts <- Matrix::Matrix(as.matrix(exp_mat), sparse = TRUE)
    seu <- CreateSeuratObject(
      counts = counts,
      project = project,
      min.cells = min_cells,
      min.features = min_features
    )
  } else {
    stop("input_type must be one of: auto, mtx, h5, rds, matrix")
  }

  seu
}

add_qc_metrics <- function(seu, mt_pattern = "^MT-") {
  DefaultAssay(seu) <- "RNA"
  seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)
  seu[["percent.ribo"]] <- PercentageFeatureSet(seu, pattern = "^RP[SL]")
  seu[["percent.hb"]] <- PercentageFeatureSet(seu, pattern = "^HB[^(P)]")
  seu
}

save_qc_plots <- function(seu, prefix, outdir) {
  qc_features <- intersect(c("nFeature_RNA", "nCount_RNA", "percent.mt", "percent.ribo", "percent.hb"), colnames(seu@meta.data))
  if (length(qc_features) > 0) {
    p_vln <- VlnPlot(seu, features = qc_features, ncol = min(3, length(qc_features)), pt.size = 0.05)
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_qc_violin.png")), p_vln, width = 12, height = 7)
  }
  if (all(c("nCount_RNA", "percent.mt") %in% colnames(seu@meta.data))) {
    p_scatter_mt <- FeatureScatter(seu, feature1 = "nCount_RNA", feature2 = "percent.mt") +
      ggtitle(paste0(prefix, " nCount_RNA vs percent.mt"))
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_ncount_vs_percent_mt.png")), p_scatter_mt, width = 7, height = 5)
  }
  if (all(c("nCount_RNA", "nFeature_RNA") %in% colnames(seu@meta.data))) {
    p_scatter_features <- FeatureScatter(seu, feature1 = "nCount_RNA", feature2 = "nFeature_RNA") +
      ggtitle(paste0(prefix, " nCount_RNA vs nFeature_RNA"))
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_ncount_vs_nfeature.png")), p_scatter_features, width = 7, height = 5)
  }
}

score_cell_cycle_if_possible <- function(seu) {
  DefaultAssay(seu) <- "RNA"
  s_genes <- Seurat::cc.genes$s.genes
  g2m_genes <- Seurat::cc.genes$g2m.genes
  s_present <- intersect(s_genes, rownames(seu))
  g2m_present <- intersect(g2m_genes, rownames(seu))
  if (length(s_present) >= 10 && length(g2m_present) >= 10) {
    seu <- CellCycleScoring(seu, s.features = s_present, g2m.features = g2m_present, set.ident = FALSE)
  } else {
    message("Skipping cell-cycle scoring because too few cell-cycle genes were found.")
  }
  seu
}

run_standard_seurat_pipeline <- function(seu, prefix, outdir) {
  set.seed(seed)
  DefaultAssay(seu) <- "RNA"

  seu <- NormalizeData(seu, normalization.method = normalization_method, scale.factor = scale_factor, verbose = FALSE)

  if (isTRUE(do_cell_cycle_scoring)) {
    seu <- score_cell_cycle_if_possible(seu)
  }

  seu <- FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable_features, verbose = FALSE)
  top10_variable <- head(VariableFeatures(seu), 10)
  variable_table <- data.frame(variable_feature_rank = seq_along(VariableFeatures(seu)), gene = VariableFeatures(seu))
  write.csv(variable_table, file.path(outdir, "tables", paste0(prefix, "_variable_features.csv")), row.names = FALSE)

  p_variable <- VariableFeaturePlot(seu)
  if (length(top10_variable) > 0) {
    p_variable <- LabelPoints(plot = p_variable, points = top10_variable, repel = TRUE)
  }
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_variable_features.png")), p_variable, width = 8, height = 6)

  vars_to_regress <- character(0)
  if (isTRUE(regress_percent_mt) && "percent.mt" %in% colnames(seu@meta.data)) vars_to_regress <- c(vars_to_regress, "percent.mt")
  if (isTRUE(regress_cell_cycle) && all(c("S.Score", "G2M.Score") %in% colnames(seu@meta.data))) {
    vars_to_regress <- c(vars_to_regress, "S.Score", "G2M.Score")
  }
  vars_to_regress <- unique(vars_to_regress)

  if (length(vars_to_regress) > 0) {
    seu <- ScaleData(seu, features = rownames(seu), vars.to.regress = vars_to_regress, verbose = FALSE)
  } else {
    seu <- ScaleData(seu, features = rownames(seu), verbose = FALSE)
  }

  npcs_actual <- min(n_pcs, length(VariableFeatures(seu)), ncol(seu) - 1)
  if (npcs_actual < 2) stop("Too few cells/features for PCA after filtering.")

  seu <- RunPCA(seu, features = VariableFeatures(seu), npcs = npcs_actual, verbose = FALSE, seed.use = seed)
  dims_use <- seq_len(min(n_pcs, ncol(Embeddings(seu, "pca"))))

  p_pca <- DimPlot(seu, reduction = "pca") + ggtitle(paste0(prefix, " PCA"))
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_pca.png")), p_pca, width = 7, height = 6)

  p_elbow <- ElbowPlot(seu, ndims = max(dims_use))
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_elbow.png")), p_elbow, width = 7, height = 5)

  p_loadings <- VizDimLoadings(seu, dims = 1:min(2, length(dims_use)), reduction = "pca")
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_pca_loadings.png")), p_loadings, width = 10, height = 7)

  p_heatmap <- DimHeatmap(seu, dims = 1:min(6, length(dims_use)), cells = min(500, ncol(seu)), balanced = TRUE, fast = FALSE)
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_pca_heatmap.png")), p_heatmap, width = 10, height = 12)

  seu <- FindNeighbors(seu, dims = dims_use, verbose = FALSE)
  seu <- FindClusters(seu, resolution = cluster_resolution, random.seed = seed, verbose = FALSE)
  seu <- RunUMAP(seu, dims = dims_use, seed.use = seed, verbose = FALSE)

  p_umap_clusters <- DimPlot(seu, reduction = "umap", label = TRUE, repel = TRUE) +
    ggtitle(paste0(prefix, " UMAP clusters"))
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_umap_clusters.png")), p_umap_clusters, width = 8, height = 6)

  if ("percent.mt" %in% colnames(seu@meta.data)) {
    p_umap_mt <- FeaturePlot(seu, features = "percent.mt", reduction = "umap") +
      ggtitle(paste0(prefix, " percent.mt"))
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_umap_percent_mt.png")), p_umap_mt, width = 7, height = 6)
  }

  if ("Phase" %in% colnames(seu@meta.data)) {
    p_umap_phase <- DimPlot(seu, reduction = "umap", group.by = "Phase") +
      ggtitle(paste0(prefix, " cell-cycle phase"))
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_umap_cell_cycle_phase.png")), p_umap_phase, width = 7, height = 6)
  }

  saveRDS(seu, file.path(outdir, "objects", paste0(prefix, "_processed.rds")))
  write.csv(seu@meta.data, file.path(outdir, "tables", paste0(prefix, "_metadata.csv")))
  umap_coords <- as.data.frame(Embeddings(seu, "umap"))
  umap_coords$cell <- rownames(umap_coords)
  umap_coords$seurat_cluster <- as.character(seu$seurat_clusters)
  write.csv(umap_coords, file.path(outdir, "tables", paste0(prefix, "_umap_coordinates.csv")), row.names = FALSE)

  seu
}

run_doubletfinder_safe <- function(seu, n_pcs = 30, doublet_rate = 0.07, pK = 0.01, run_pk_sweep = FALSE) {
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) {
    message("DoubletFinder not installed. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  if (!"seurat_clusters" %in% colnames(seu@meta.data)) {
    message("No seurat_clusters found. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }

  dims_available <- if ("pca" %in% names(seu@reductions)) ncol(Embeddings(seu, "pca")) else 0
  if (dims_available < 2) {
    message("PCA not available for DoubletFinder. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }
  pcs_use <- seq_len(min(n_pcs, dims_available))

  if (isTRUE(run_pk_sweep)) {
    pK <- tryCatch({
      sweep.res <- DoubletFinder::paramSweep(seu, PCs = pcs_use, sct = FALSE)
      sweep.stats <- DoubletFinder::summarizeSweep(sweep.res, GT = FALSE)
      bcmvn <- DoubletFinder::find.pK(sweep.stats)
      as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
    }, error = function(e) {
      message("DoubletFinder pK sweep failed: ", e$message)
      pK
    })
  }

  annotations <- as.character(seu@meta.data$seurat_clusters)
  homotypic_prop <- tryCatch(
    DoubletFinder::modelHomotypic(annotations),
    error = function(e) {
      message("modelHomotypic failed: ", e$message)
      0
    }
  )

  n_exp <- round(doublet_rate * ncol(seu))
  n_exp_adj <- round(n_exp * (1 - homotypic_prop))

  seu_df <- tryCatch(
    DoubletFinder::doubletFinder(
      seu,
      PCs = pcs_use,
      pN = 0.25,
      pK = as.numeric(pK),
      nExp = n_exp_adj,
      reuse.pANN = NULL,
      sct = FALSE
    ),
    error = function(e) {
      message("doubletFinder() failed: ", e$message)
      seu$doublet_status <- "Singlet"
      return(seu)
    }
  )

  df_col <- grep("DF.classifications", colnames(seu_df@meta.data), value = TRUE)
  df_col <- if (length(df_col) > 0) df_col[1] else NA

  if (is.na(df_col)) {
    seu_df$doublet_status <- "Singlet"
  } else {
    seu_df$doublet_status <- as.character(seu_df@meta.data[[df_col]])
  }

  seu_df
}

annotate_pbmc_by_markers <- function(seu, outdir, prefix = "final") {
  DefaultAssay(seu) <- "RNA"
  if (inherits(seu[["RNA"]], "Assay5")) {
    seu[["RNA"]] <- JoinLayers(seu[["RNA"]])
  }

  marker_sets <- list(
    "Naive/central memory CD4 T" = c("IL7R", "CCR7", "LTB", "TCF7", "LEF1", "SELL"),
    "Memory/activated CD4 T" = c("IL7R", "S100A4", "ANXA1", "CD40LG"),
    "CD8 T" = c("CD8A", "CD8B", "GZMK", "CCL5", "NKG7"),
    "NK" = c("GNLY", "NKG7", "KLRD1", "KLRF1", "PRF1", "GZMB"),
    "B" = c("MS4A1", "CD79A", "CD79B", "BANK1", "CD74"),
    "Plasma" = c("MZB1", "IGJ", "SDC1", "XBP1", "JCHAIN"),
    "CD14 monocyte" = c("CD14", "LYZ", "LST1", "S100A8", "S100A9", "VCAN"),
    "FCGR3A monocyte" = c("FCGR3A", "MS4A7", "LST1", "IFITM3", "AIF1"),
    "Dendritic cell" = c("FCER1A", "CST3", "CLEC10A", "CD1C", "HLA-DQA1"),
    "Plasmacytoid DC" = c("IL3RA", "GZMB", "IRF7", "TCF4", "LILRA4"),
    "Platelet" = c("PPBP", "PF4", "GP9", "NRGN", "SDPR")
  )

  expr <- GetAssayData(seu, assay = "RNA", layer = "data")
  clusters <- as.character(seu$seurat_clusters)
  cell_types <- names(marker_sets)
  score_mat <- matrix(NA_real_, nrow = ncol(seu), ncol = length(marker_sets), dimnames = list(colnames(seu), cell_types))

  for (ct in cell_types) {
    genes <- intersect(marker_sets[[ct]], rownames(expr))
    if (length(genes) > 0) {
      score_mat[, ct] <- Matrix::colMeans(expr[genes, , drop = FALSE])
    }
  }

  score_df <- as.data.frame(score_mat)
  score_df$cluster <- clusters
  cluster_scores <- aggregate(score_df[, cell_types, drop = FALSE], by = list(cluster = score_df$cluster), FUN = function(x) mean(x, na.rm = TRUE))

  assigned <- vapply(seq_len(nrow(cluster_scores)), function(i) {
    vals <- as.numeric(cluster_scores[i, cell_types])
    if (all(is.na(vals))) {
      "Unknown"
    } else {
      cell_types[which.max(vals)]
    }
  }, character(1))

  annotation_map <- data.frame(
    seurat_cluster = as.character(cluster_scores$cluster),
    pbmc_cell_type = assigned,
    stringsAsFactors = FALSE
  )

  cell_annotation <- annotation_map$pbmc_cell_type[match(clusters, annotation_map$seurat_cluster)]
  cell_annotation[is.na(cell_annotation)] <- "Unknown"
  seu$pbmc_cell_type <- cell_annotation

  write.csv(annotation_map, file.path(outdir, "tables", paste0(prefix, "_pbmc_cluster_annotation_map.csv")), row.names = FALSE)
  write.csv(cluster_scores, file.path(outdir, "tables", paste0(prefix, "_pbmc_marker_scores_by_cluster.csv")), row.names = FALSE)

  p_annotated <- DimPlot(seu, reduction = "umap", group.by = "pbmc_cell_type", label = TRUE, repel = TRUE) +
    ggtitle("PBMC cell type annotation")
  safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_umap_pbmc_cell_types.png")), p_annotated, width = 10, height = 7)

  selected_markers <- unique(unlist(marker_sets))
  selected_markers <- intersect(selected_markers, rownames(seu))
  if (length(selected_markers) > 0) {
    top_markers <- head(selected_markers, 40)
    p_dot <- DotPlot(seu, features = top_markers, group.by = "pbmc_cell_type") +
      RotatedAxis() +
      ggtitle("Canonical PBMC markers")
    safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_pbmc_marker_dotplot.png")), p_dot, width = 14, height = 7)
  }

  seu
}

find_and_save_markers <- function(seu, outdir, prefix = "final") {
  DefaultAssay(seu) <- "RNA"
  if (inherits(seu[["RNA"]], "Assay5")) {
    seu[["RNA"]] <- JoinLayers(seu[["RNA"]])
  }

  if (!"seurat_clusters" %in% colnames(seu@meta.data)) {
    stop("Cannot find markers: seurat_clusters not found.")
  }

  Idents(seu) <- "seurat_clusters"
  n_clusters <- length(levels(Idents(seu)))

  if (n_clusters < 2) {
    message("Only one cluster detected; skipping FindAllMarkers.")
    return(data.frame())
  }

  markers <- FindAllMarkers(
    seu,
    only.pos = TRUE,
    min.pct = 0.25,
    logfc.threshold = 0.25,
    test.use = "wilcox"
  )

  write.csv(markers, file.path(outdir, "tables", paste0(prefix, "_cluster_markers_all.csv")), row.names = FALSE)

  logfc_col <- if ("avg_log2FC" %in% colnames(markers)) "avg_log2FC" else if ("avg_logFC" %in% colnames(markers)) "avg_logFC" else NA
  if (!is.na(logfc_col) && nrow(markers) > 0) {
    marker_split <- split(markers, markers$cluster)
    top_markers <- do.call(rbind, lapply(marker_split, function(x) {
      x <- x[order(x[[logfc_col]], decreasing = TRUE), , drop = FALSE]
      head(x, 10)
    }))
    write.csv(top_markers, file.path(outdir, "tables", paste0(prefix, "_cluster_markers_top10.csv")), row.names = FALSE)

    heatmap_genes <- unique(top_markers$gene)
    heatmap_genes <- intersect(heatmap_genes, rownames(seu))
    if (length(heatmap_genes) > 1) {
      p_heatmap <- DoHeatmap(seu, features = heatmap_genes, group.by = "seurat_clusters") +
        ggtitle("Top cluster markers")
      safe_ggsave(file.path(outdir, "plots", paste0(prefix, "_top_marker_heatmap.png")), p_heatmap, width = 12, height = 12)
    }
  }

  markers
}

