detect_input <- function(data_dir, input_file, input_type) {
  if (input_type != "auto") {
    return(list(type = input_type, path = if (nzchar(input_file)) input_file else data_dir))
  }
  if (nzchar(input_file)) {
    ext <- tolower(basename(input_file))
    if (grepl("\\.h5$", ext)) return(list(type = "h5", path = input_file))
    if (grepl("\\.rds$", ext)) return(list(type = "rds", path = input_file))
    if (grepl("\\.(tsv|txt|csv)(\\.gz)?$", ext)) return(list(type = "matrix", path = input_file))
  }
  h5_candidates <- list.files(data_dir, pattern = "\\.h5$", full.names = TRUE)
  has_mtx <- any(file.exists(file.path(data_dir, c("matrix.mtx", "matrix.mtx.gz"))))
  has_barcodes <- any(file.exists(file.path(data_dir, c("barcodes.tsv", "barcodes.tsv.gz"))))
  has_features <- any(file.exists(file.path(data_dir, c("features.tsv", "features.tsv.gz", "genes.tsv", "genes.tsv.gz"))))
  if (has_mtx && has_barcodes && has_features) return(list(type = "mtx", path = data_dir))
  if (length(h5_candidates) > 0) return(list(type = "h5", path = h5_candidates[1]))
  stop("No supported raw-count input detected. Provide a 10X MTX directory in SCRNA_DATA_DIR, or set SCRNA_INPUT_FILE and SCRNA_INPUT_TYPE.")
}

load_counts_or_object <- function(input) {
  if (input$type == "mtx") {
    counts <- Read10X(data.dir = input$path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(CreateSeuratObject(
      counts = counts,
      project = params$project_name,
      min.cells = params$min_cells,
      min.features = params$min_features_create
    ))
  }
  if (input$type == "h5") {
    counts <- Read10X_h5(filename = input$path)
    if (is.list(counts)) {
      if ("Gene Expression" %in% names(counts)) {
        counts <- counts[["Gene Expression"]]
      } else {
        counts <- counts[[1]]
      }
    }
    return(CreateSeuratObject(
      counts = counts,
      project = params$project_name,
      min.cells = params$min_cells,
      min.features = params$min_features_create
    ))
  }
  if (input$type == "rds") {
    obj <- readRDS(input$path)
    if (!inherits(obj, "Seurat")) stop("RDS input is not a Seurat object.")
    return(obj)
  }
  if (input$type == "matrix") {
    sep <- if (grepl("\\.csv(\\.gz)?$", input$path, ignore.case = TRUE)) "," else "\t"
    mat <- read.table(input$path, header = TRUE, row.names = 1, sep = sep, check.names = FALSE, stringsAsFactors = FALSE)
    rownames(mat) <- make.unique(rownames(mat))
    counts <- Matrix::Matrix(as.matrix(mat), sparse = TRUE)
    return(CreateSeuratObject(
      counts = counts,
      project = params$project_name,
      min.cells = params$min_cells,
      min.features = params$min_features_create
    ))
  }
  stop("Unsupported input_type. Use auto, mtx, h5, rds, or matrix.")
}

