run_basic_pipeline <- function(obj, label) {
  DefaultAssay(obj) <- "RNA"
  obj <- NormalizeData(obj, normalization.method = "LogNormalize", scale.factor = 10000, verbose = FALSE)
  obj <- FindVariableFeatures(obj, selection.method = "vst", nfeatures = params$n_variable, verbose = FALSE)
  cc_s <- Seurat::cc.genes$s.genes
  cc_g2m <- Seurat::cc.genes$g2m.genes
  cc_s <- cc_s[cc_s %in% rownames(obj)]
  cc_g2m <- cc_g2m[cc_g2m %in% rownames(obj)]
  if (length(cc_s) >= 5 && length(cc_g2m) >= 5) {
    obj <- CellCycleScoring(obj, s.features = cc_s, g2m.features = cc_g2m, set.ident = FALSE)
  }
  regress_vars <- intersect(c("percent.mt"), colnames(obj@meta.data))
  obj <- ScaleData(obj, vars.to.regress = regress_vars, verbose = FALSE)
  obj <- RunPCA(obj, npcs = params$n_pcs, verbose = FALSE)
  dims_use <- seq_len(min(params$dims_use, length(Embeddings(obj, "pca")[1, ])))
  obj <- FindNeighbors(obj, dims = dims_use, verbose = FALSE)
  obj <- FindClusters(obj, resolution = params$resolution, verbose = FALSE)
  obj <- RunUMAP(obj, dims = dims_use, verbose = FALSE)
  save_obj(obj, paste0(label, "_processed.rds"))
  save_plot(ElbowPlot(obj, ndims = params$n_pcs) + ggtitle(paste(label, "PCA elbow")), paste0(label, "_elbow_plot.png"))
  save_plot(DimPlot(obj, reduction = "pca", group.by = "seurat_clusters") + ggtitle(paste(label, "PCA clusters")), paste0(label, "_pca_clusters.png"))
  save_plot(DimPlot(obj, reduction = "umap", label = TRUE, repel = TRUE) + ggtitle(paste(label, "UMAP clusters")), paste0(label, "_umap_clusters.png"))
  obj
}

run_doubletfinder_safe <- function(obj, n_pcs, doublet_rate, pK, run_pk_sweep) {
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) {
    message("DoubletFinder is not available; marking all cells as Singlet.")
    obj$doublet_status <- "Singlet"
    return(obj)
  }
  if (!"seurat_clusters" %in% colnames(obj@meta.data)) {
    message("No seurat_clusters metadata found; marking all cells as Singlet.")
    obj$doublet_status <- "Singlet"
    return(obj)
  }
  dims <- seq_len(min(n_pcs, ncol(Embeddings(obj, "pca"))))
  if (isTRUE(run_pk_sweep)) {
    pK <- tryCatch({
      sweep.res <- DoubletFinder::paramSweep(obj, PCs = dims, sct = FALSE)
      sweep.stats <- DoubletFinder::summarizeSweep(sweep.res, GT = FALSE)
      bcmvn <- DoubletFinder::find.pK(sweep.stats)
      as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
    }, error = function(e) {
      message("DoubletFinder pK sweep failed: ", e$message)
      pK
    })
  }
  annotations <- as.character(obj$seurat_clusters)
  homotypic_prop <- tryCatch(
    DoubletFinder::modelHomotypic(annotations),
    error = function(e) {
      message("DoubletFinder modelHomotypic failed: ", e$message)
      0
    }
  )
  n_exp <- round(doublet_rate * ncol(obj))
  n_exp_adj <- max(1, round(n_exp * (1 - homotypic_prop)))
  obj_df <- tryCatch(
    DoubletFinder::doubletFinder(
      obj,
      PCs = dims,
      pN = 0.25,
      pK = as.numeric(pK),
      nExp = n_exp_adj,
      reuse.pANN = NULL,
      sct = FALSE
    ),
    error = function(e) {
      message("DoubletFinder failed: ", e$message)
      obj$doublet_status <- "Singlet"
      obj
    }
  )
  df_col <- grep("DF.classifications", colnames(obj_df@meta.data), value = TRUE)
  if (length(df_col) > 0) {
    obj_df$doublet_status <- as.character(obj_df@meta.data[[df_col[1]]])
  } else if (!"doublet_status" %in% colnames(obj_df@meta.data)) {
    obj_df$doublet_status <- "Singlet"
  }
  obj_df
}

annotate_pbmc_by_markers <- function(obj) {
  marker_sets <- list(
    "CD4 T cells" = c("IL7R", "CCR7", "LTB", "CD3D", "CD3E", "TRAC"),
    "CD8 T cells" = c("CD8A", "CD8B", "GZMK", "CD3D", "CD3E", "TRAC"),
    "NK cells" = c("NKG7", "GNLY", "KLRD1", "PRF1", "GZMB"),
    "B cells" = c("MS4A1", "CD79A", "CD79B", "BANK1", "CD74"),
    "Plasma cells" = c("MZB1", "JCHAIN", "IGKC", "IGHG1", "SDC1"),
    "CD14 monocytes" = c("LYZ", "S100A8", "S100A9", "CD14", "VCAN", "FCN1"),
    "FCGR3A monocytes" = c("FCGR3A", "MS4A7", "LST1", "IFITM3", "AIF1"),
    "Dendritic cells" = c("FCER1A", "CST3", "CLEC10A", "CD1C"),
    "Plasmacytoid DCs" = c("IL3RA", "GZMB", "IRF7", "TCF4", "CLEC4C"),
    "Platelets" = c("PPBP", "PF4", "TUBB1", "NRGN")
  )
  DefaultAssay(obj) <- "RNA"
  for (nm in names(marker_sets)) {
    genes <- marker_sets[[nm]][marker_sets[[nm]] %in% rownames(obj)]
    if (length(genes) > 0) {
      obj <- AddModuleScore(obj, features = list(genes), name = paste0(gsub("[^A-Za-z0-9]", "_", nm), "_Score"), assay = "RNA")
    }
  }
  score_cols <- grep("_Score1$", colnames(obj@meta.data), value = TRUE)
  cluster_ids <- sort(unique(as.character(obj$seurat_clusters)))
  cluster_annotation <- setNames(rep("Unassigned", length(cluster_ids)), cluster_ids)
  if (length(score_cols) > 0) {
    score_means <- aggregate(obj@meta.data[, score_cols, drop = FALSE], by = list(cluster = as.character(obj$seurat_clusters)), FUN = mean)
    rownames(score_means) <- score_means$cluster
    score_mat <- as.matrix(score_means[, score_cols, drop = FALSE])
    cleaned_names <- sub("_Score1$", "", colnames(score_mat))
    cleaned_names <- gsub("_", " ", cleaned_names)
    best <- cleaned_names[max.col(score_mat, ties.method = "first")]
    names(best) <- rownames(score_mat)
    cluster_annotation[names(best)] <- best
  }
  obj$pbmc_cell_type <- unname(cluster_annotation[as.character(obj$seurat_clusters)])
  Idents(obj) <- obj$pbmc_cell_type
  attr(obj, "pbmc_cluster_annotation") <- cluster_annotation
  obj
}

