make_seurat_from_file <- function(f) {
  ext <- tolower(tools::file_ext(f))
  if (ext == "rds") {
    obj <- readRDS(f)
    if (inherits(obj, "Seurat")) {
      return(obj)
    }
    if (inherits(obj, "SingleCellExperiment")) {
      return(as.Seurat(obj, data = NULL))
    }
    if (is.matrix(obj) || inherits(obj, "dgCMatrix")) {
      return(CreateSeuratObject(counts = obj, project = basename(f), min.cells = 3, min.features = 200))
    }
    stop("Unsupported RDS object in file: ", f)
  } else if (ext == "h5") {
    counts <- Read10X_h5(f)
    return(CreateSeuratObject(counts = counts, project = basename(f), min.cells = 3, min.features = 200))
  } else if (ext == "mtx") {
    dir <- dirname(f)
    counts <- Read10X(data.dir = dir)
    return(CreateSeuratObject(counts = counts, project = basename(dir), min.cells = 3, min.features = 200))
  } else {
    stop("Unsupported file type: ", f)
  }
}

