run_doubletfinder_safe <- function(seurat_object, n_pcs = 20, doublet_rate = 0.07) {
  seurat_object$doublet_status <- "Singlet"
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) return(seurat_object)
  if (!"seurat_clusters" %in% colnames(seurat_object@meta.data)) return(seurat_object)
  out <- tryCatch({
    pK <- 0.09
    nExp <- max(1, round(ncol(seurat_object) * doublet_rate))
    seurat_object <- DoubletFinder::doubletFinder(
      seurat_object,
      PCs = 1:n_pcs,
      pN = 0.25,
      pK = pK,
      nExp = nExp,
      reuse.pANN = NULL,
      sct = FALSE
    )
    cls_col <- grep("^DF.classifications", colnames(seurat_object@meta.data), value = TRUE)
    if (length(cls_col) > 0) seurat_object$doublet_status <- as.character(seurat_object@meta.data[[cls_col[1]]])
    seurat_object
  }, error = function(e) {
    seurat_object$doublet_status <- "Singlet"
    seurat_object
  })
  out
}

