min_cells <- 3
min_features <- 200
mt_pattern <- "^MT-"
min_feat <- 200
max_feat <- 2500
min_counts <- 800
max_counts <- Inf
max_mt <- 5
norm_method <- "lognorm"
scale_factor <- 10000
regress_cell_cycle <- FALSE
n_variable <- 2000
selection_method <- "vst"
scale_all_genes <- FALSE
vars_to_regress <- NULL
n_pcs_compute <- 50
n_pcs <- 20
resolution <- 0.5
seed <- 42

if (input_type == "mtx") {
  counts <- Read10X(data.dir = data_path)
  seu <- CreateSeuratObject(counts = counts, project = project_name, min.cells = min_cells, min.features = min_features)
} else if (input_type == "h5") {
  counts <- Read10X_h5(filename = data_path)
  seu <- CreateSeuratObject(counts = counts, project = project_name, min.cells = min_cells, min.features = min_features)
} else if (input_type == "rds") {
  seu <- readRDS(data_path)
} else if (input_type == "sce") {
  suppressPackageStartupMessages(library(SingleCellExperiment))
  sce <- readRDS(data_path)
  seu <- as.Seurat(sce, data = NULL)
} else if (input_type == "matrix") {
  exp_mat <- read.table(file = data_path, header = TRUE, as.is = TRUE, row.names = 1)
  seu <- CreateSeuratObject(counts = Matrix::Matrix(as.matrix(exp_mat), sparse = TRUE), project = project_name, min.cells = min_cells, min.features = min_features)
} else {
  stop("input_type must be one of: mtx, h5, rds, sce, matrix")
}

seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)

keep <- seu$nFeature_RNA > min_feat &
  seu$nFeature_RNA < max_feat &
  seu$percent.mt < max_mt

if (min_counts > 0) keep <- keep & seu$nCount_RNA > min_counts
if (is.finite(max_counts)) keep <- keep & seu$nCount_RNA < max_counts

seu_filtered <- subset(seu, cells = colnames(seu)[keep])

if (norm_method == "lognorm") {
  seu_filtered <- NormalizeData(seu_filtered, normalization.method = "LogNormalize", scale.factor = scale_factor)
} else if (norm_method == "sctransform") {
  seu_filtered <- SCTransform(seu_filtered, verbose = FALSE)
} else {
  stop("norm_method must be 'lognorm' or 'sctransform'")
}

s_genes <- Seurat::cc.genes$s.genes
g2m_genes <- Seurat::cc.genes$g2m.genes
seu_filtered <- CellCycleScoring(seu_filtered, s.features = s_genes, g2m.features = g2m_genes, set.ident = FALSE)

if (regress_cell_cycle) {
  vars_to_regress <- c("S.Score", "G2M.Score")
}

seu_filtered <- FindVariableFeatures(seu_filtered, selection.method = selection_method, nfeatures = n_variable)
top10 <- head(VariableFeatures(seu_filtered), 10)
p1 <- VariableFeaturePlot(seu_filtered)
p2 <- LabelPoints(plot = p1, points = top10, repel = TRUE, xnudge = 0, ynudge = 0)
print(p2)

features_to_scale <- if (scale_all_genes) rownames(seu_filtered) else VariableFeatures(seu_filtered)
seu_filtered <- ScaleData(seu_filtered, features = features_to_scale, vars.to.regress = vars_to_regress)

seu_filtered <- RunPCA(seu_filtered, features = VariableFeatures(object = seu_filtered), npcs = n_pcs_compute, verbose = FALSE)
print(seu_filtered[["pca"]], dims = 1:5, nfeatures = 5)
print(VizDimLoadings(seu_filtered, dims = 1:2, reduction = "pca"))
print(DimPlot(seu_filtered, reduction = "pca") + NoLegend())
print(DimHeatmap(seu_filtered, dims = 1:15, cells = 500, balanced = TRUE))
print(ElbowPlot(seu_filtered, ndims = n_pcs_compute))

seu_filtered <- FindNeighbors(seu_filtered, dims = 1:n_pcs, reduction = "pca", verbose = FALSE)
seu_filtered <- FindClusters(seu_filtered, resolution = resolution, verbose = FALSE)
seu_filtered <- RunUMAP(seu_filtered, dims = 1:n_pcs, reduction = "pca", verbose = FALSE)

print(DimPlot(seu_filtered, reduction = "umap", label = TRUE) + ggtitle("PBMC UMAP"))
print(DimPlot(seu_filtered, reduction = "umap", group.by = "seurat_clusters", label = TRUE) + ggtitle("Clusters"))

if (requireNamespace("DoubletFinder", quietly = TRUE)) {
  suppressPackageStartupMessages(library(DoubletFinder))
  seu_filtered$seurat_clusters <- as.character(seu_filtered$seurat_clusters)
  sweep.res.list <- tryCatch(
    paramSweep_v3(seu_filtered, PCs = 1:n_pcs, sct = (norm_method == "sctransform")),
    error = function(e) NULL
  )
  if (!is.null(sweep.res.list)) {
    sweep.stats <- tryCatch(summarizeSweep(sweep.res.list, GT = FALSE), error = function(e) NULL)
    bcmvn <- tryCatch(find.pK(sweep.stats), error = function(e) NULL)
    if (!is.null(bcmvn) && nrow(bcmvn) > 0) {
      pk <- as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
      if (is.na(pk)) pk <- 0.09
    } else {
      pk <- 0.09
    }
  } else {
    pk <- 0.09
  }
  homotypic.prop <- tryCatch(modelHomotypic(seu_filtered$seurat_clusters), error = function(e) 0)
  nExp_poi <- round(0.07 * ncol(seu_filtered))
  nExp_poi.adj <- max(1, round(nExp_poi * (1 - homotypic.prop)))
  seu_filtered <- tryCatch(
    doubletFinder(seu_filtered, PCs = 1:n_pcs, pN = 0.25, pK = pk, nExp = nExp_poi.adj, reuse.pANN = NULL, sct = (norm_method == "sctransform")),
    error = function(e) {
      seu_filtered$doublet_status <- "Singlet"
      seu_filtered
    }
  )
  df_cols <- grep("DF.classifications", colnames(seu_filtered@meta.data), value = TRUE)
  if (length(df_cols) > 0) {
    seu_filtered$doublet_status <- seu_filtered@meta.data[[df_cols[1]]]
  } else if (!"doublet_status" %in% colnames(seu_filtered@meta.data)) {
    seu_filtered$doublet_status <- "Singlet"
  }
  seu_singlets <- subset(seu_filtered, subset = doublet_status == "Singlet")
} else {
  seu_filtered$doublet_status <- "Singlet"
  seu_singlets <- seu_filtered
}

markers <- FindAllMarkers(seu_singlets, only.pos = TRUE, min.pct = 0.25, logfc.threshold = 0.25)
write.csv(markers, file = "PBMC_cluster_markers.csv", row.names = FALSE)

cluster_ids <- levels(Idents(seu_singlets))
cluster_annotation <- setNames(paste0("Cluster_", cluster_ids), cluster_ids)
seu_singlets$cell_type <- plyr::mapvalues(as.character(Idents(seu_singlets)), from = names(cluster_annotation), to = unname(cluster_annotation))
Idents(seu_singlets) <- "cell_type"

print(DimPlot(seu_singlets, reduction = "umap", label = TRUE) + ggtitle("Annotated PBMC UMAP"))
saveRDS(seu_singlets, file = "PBMC_seurat_final.rds")
sessionInfo()

