read_10x_auto <- function(path) {
  if (file.exists(file.path(path, "filtered_feature_bc_matrix.h5"))) {
    return(Read10X_h5(file.path(path, "filtered_feature_bc_matrix.h5")))
  }
  if (file.exists(file.path(path, "matrix.mtx")) && (file.exists(file.path(path, "features.tsv")) || file.exists(file.path(path, "genes.tsv")))) {
    return(Read10X(data.dir = path))
  }
  stop("No valid 10X files found in: ", path)
}

