library(Seurat)
library(ggplot2)
library(dplyr)

# Set seed for reproducibility
set.seed(42)

# 1. Identify the 3 single-cell files in the working directory.
# We look for common formats: .rds, .h5, or matrix files (csv, tsv, txt).
all_files <- list.files(path = ".", pattern = "\\.(rds|h5|csv|tsv|txt)$", ignore.case = TRUE)

# If files are found, use the first 3. Otherwise, fall back to standard placeholder names in the working directory.
if (length(all_files) >= 3) {
  files_to_load <- all_files[1:3]
} else {
  files_to_load <- c("sample1.rds", "sample2.rds", "sample3.rds")
}

cat("Files to be loaded:\n")
print(files_to_load)

# Helper function to load a single file and create a Seurat object
load_sc_file <- function(filepath, project_name) {
  ext <- tools::file_ext(filepath)

  if (tolower(ext) == "rds") {
    data <- readRDS(filepath)
    if (inherits(data, "Seurat")) {
      return(data)
    } else {
      # If it is a count matrix, ensure unique feature names
      rownames(data) <- make.unique(as.character(rownames(data)))
      seu <- CreateSeuratObject(counts = data, project = project_name, min.cells = 3, min.features = 200)
      return(seu)
    }
  } else if (tolower(ext) == "h5") {
    counts <- Read10X_h5(filename = filepath)
    # Ensure unique feature names
    if (inherits(counts, "list")) {
      # Multi-modal h5
      for (mod in names(counts)) {
        rownames(counts[[mod]]) <- make.unique(as.character(rownames(counts[[mod]])))
      }
    } else {
      rownames(counts) <- make.unique(as.character(rownames(counts)))
    }
    seu <- CreateSeuratObject(counts = counts, project = project_name, min.cells = 3, min.features = 200)
    return(seu)
  } else if (tolower(ext) %in% c("csv", "tsv", "txt")) {
    sep <- ifelse(tolower(ext) == "csv", ",", "\t")
    exp_mat <- read.table(file = filepath, header = TRUE, sep = sep, as.is = TRUE, row.names = 1)
    rownames(exp_mat) <- make.unique(as.character(rownames(exp_mat)))
    seu <- CreateSeuratObject(
      counts       = Matrix::Matrix(as.matrix(exp_mat), sparse = TRUE),
      project      = project_name,
      min.cells    = 3,
      min.features = 200
    )
    return(seu)
  } else {
    stop("Unsupported file format: ", ext)
  }
}

# Load the 3 files
seu_list <- list()
for (i in seq_along(files_to_load)) {
  proj_name <- paste0("PBMC_Sample_", i)
  seu_list[[i]] <- load_sc_file(files_to_load[i], proj_name)
}

# Merge the objects into a single Seurat object
if (length(seu_list) == 3) {
  pbmc_merged <- merge(seu_list[[1]], y = c(seu_list[[2]], seu_list[[3]]), add.cell.ids = c("S1", "S2", "S3"))
} else if (length(seu_list) == 2) {
  pbmc_merged <- merge(seu_list[[1]], y = seu_list[[2]], add.cell.ids = c("S1", "S2"))
} else {
  pbmc_merged <- seu_list[[1]]
}

# 2. Preprocessing & QC
# Compute mitochondrial percentage (using "^MT-" for human PBMCs)
pbmc_merged[["percent.mt"]] <- PercentageFeatureSet(pbmc_merged, pattern = "^MT-")

# Filter cells based on standard QC thresholds
pbmc_merged <- subset(
  pbmc_merged,
  subset = nFeature_RNA > 200 & nFeature_RNA < 2500 & percent.mt < 5
)

# 3. Normalisation & Feature Selection
# Log-normalise the data
pbmc_merged <- NormalizeData(pbmc_merged, normalization.method = "LogNormalize", scale.factor = 10000)

# Identify highly variable genes
pbmc_merged <- FindVariableFeatures(pbmc_merged, selection.method = "vst", nfeatures = 2000)

# 4. Scaling & Dimensionality Reduction
# Scale the data (only variable features to speed up computation)
pbmc_merged <- ScaleData(pbmc_merged, features = VariableFeatures(pbmc_merged))

# Run Principal Component Analysis (PCA)
pbmc_merged <- RunPCA(pbmc_merged, features = VariableFeatures(pbmc_merged), npcs = 30, verbose = FALSE)

# 5. Clustering & Visualisation
# Build the Shared Nearest Neighbor (SNN) graph (using top 20 PCs)
pbmc_merged <- FindNeighbors(pbmc_merged, dims = 1:20)

# Cluster cells using Louvain algorithm
pbmc_merged <- FindClusters(pbmc_merged, resolution = 0.5)

# Run non-linear dimensional reduction (UMAP)
pbmc_merged <- RunUMAP(pbmc_merged, dims = 1:20, verbose = FALSE)

# Plot final UMAP
umap_plot <- DimPlot(pbmc_merged, reduction = "umap", label = TRUE, repel = TRUE) +
  ggtitle("UMAP Clustering of Merged PBMC Samples") +
  theme_minimal()

print(umap_plot)

library(Seurat)
library(dplyr)
library(ggplot2)

# PARAMETERS
set.seed(42)
data_dir     <- "."          # folder containing the three 10x samples
input_type   <- "mtx"        # 10x Genomics output
min_cells    <- 3
min_features <- 200
min_feat     <- 200
max_feat     <- 2500
max_mt       <- 5
n_variable   <- 2000
n_pcs        <- 10
resolution   <- 0.5
doublet_rate <- 0.07
pK_fixed     <- 0.01
run_pk_sweep <- FALSE
mt_pattern   <- "^MT-"       # "^MT-" human, "^mt-" mouse

# Sample metadata — one row per 10x sample folder
sample_metadata <- data.frame(
  file      = c("sample1", "sample2", "sample3"),
  name      = c("PBMC1",   "PBMC2",   "PBMC3"),
  stringsAsFactors = FALSE
)

# ---- Load each 10x sample and create a Seurat object ----
load_sample <- function(i, sample_metadata, data_dir, input_type,
                        min_cells, min_features) {
  filepath <- file.path(data_dir, sample_metadata$file[i])
  if (input_type == "rds") {
    counts <- readRDS(filepath)
    if (inherits(counts, "Seurat")) return(counts)
  } else if (input_type == "mtx") {
    counts <- Read10X(data.dir = filepath)
  } else if (input_type == "h5") {
    counts <- Read10X_h5(filename = filepath)
  }
  CreateSeuratObject(counts = counts, project = sample_metadata$name[i],
                     min.cells = min_cells, min.features = min_features)
}

sample_list <- lapply(seq_len(nrow(sample_metadata)), function(i) {
  seu <- load_sample(i, sample_metadata, data_dir, input_type,
                     min_cells, min_features)
  for (col in setdiff(colnames(sample_metadata), "file")) {
    seu[[col]] <- sample_metadata[[col]][i]
  }
  seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)
  cat("Loaded:", sample_metadata$name[i],
      "| Cells:", ncol(seu), "| Genes:", nrow(seu), "\n")
  seu
})
names(sample_list) <- sample_metadata$name

for (nm in names(sample_list)) {
  print(VlnPlot(sample_list[[nm]],
                features = c("nFeature_RNA", "nCount_RNA", "percent.mt")) +
          ggtitle(nm))
}

# ============================================================
# DoubletFinder must be run PER SAMPLE, on a fully processed object:
# filter -> NormalizeData -> FindVariableFeatures -> ScaleData ->
# RunPCA -> FindNeighbors -> FindClusters -> RunUMAP -> DoubletFinder
# ============================================================
run_doubletfinder_safe <- function(seu, n_pcs = 10, doublet_rate = 0.07,
                                   pK = 0.01, run_pk_sweep = FALSE) {
  if (!requireNamespace("DoubletFinder", quietly = TRUE)) {
    message("DoubletFinder not installed. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }
  if (!"seurat_clusters" %in% colnames(seu@meta.data)) {
    message("No seurat_clusters found. Marking all cells as Singlet.")
    seu$doublet_status <- "Singlet"
    return(seu)
  }
  if (isTRUE(run_pk_sweep)) {
    sweep.res   <- DoubletFinder::paramSweep(seu, PCs = 1:n_pcs, sct = FALSE)
    sweep.stats <- DoubletFinder::summarizeSweep(sweep.res, GT = FALSE)
    bcmvn       <- DoubletFinder::find.pK(sweep.stats)
    pK <- as.numeric(as.character(bcmvn$pK[which.max(bcmvn$BCmetric)]))
    message("Optimal pK: ", pK)
  }
  annotations    <- as.character(seu@meta.data$seurat_clusters)
  homotypic_prop <- tryCatch(
    DoubletFinder::modelHomotypic(annotations),
    error = function(e) { message("modelHomotypic failed: ", e$message); 0 }
  )
  n_exp     <- round(doublet_rate * ncol(seu))
  n_exp_adj <- round(n_exp * (1 - homotypic_prop))
  message("Expected doublets (raw):      ", n_exp)
  message("Expected doublets (adjusted): ", n_exp_adj)

  seu_df <- tryCatch(
    DoubletFinder::doubletFinder(
      seu, PCs = 1:n_pcs, pN = 0.25, pK = as.numeric(pK),
      nExp = n_exp_adj, reuse.pANN = NULL, sct = FALSE
    ),
    error = function(e) {
      message("doubletFinder() failed: ", e$message)
      message("Fallback: marking all cells as Singlet.")
      seu$doublet_status <- "Singlet"
      return(seu)
    }
  )
  df_col <- grep("DF.classifications", colnames(seu_df@meta.data), value = TRUE)
  df_col <- if (length(df_col) > 0) df_col[1] else NA
  if (is.na(df_col)) {
    message("No DF.classifications column found. Using fallback.")
    seu_df$doublet_status <- "Singlet"
  } else {
    seu_df$doublet_status <- as.character(seu_df@meta.data[[df_col]])
    print(table(seu_df$doublet_status))
  }
  seu_df
}

process_and_detect_doublets <- function(seu) {
  seu <- subset(seu, subset = nFeature_RNA > min_feat &
                  nFeature_RNA < max_feat & percent.mt < max_mt)
  seu <- NormalizeData(seu)
  seu <- FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable)
  seu <- ScaleData(seu)
  seu <- RunPCA(seu, npcs = n_pcs)
  seu <- FindNeighbors(seu, dims = 1:n_pcs)
  seu <- FindClusters(seu, resolution = resolution)
  seu <- RunUMAP(seu, dims = 1:n_pcs)
  seu <- run_doubletfinder_safe(seu, n_pcs = n_pcs, doublet_rate = doublet_rate,
                                pK = pK_fixed, run_pk_sweep = run_pk_sweep)
  seu
}

sample_list_df <- lapply(names(sample_list), function(nm) {
  cat("\n==== Doublet detection:", nm, "====\n")
  seu <- process_and_detect_doublets(sample_list[[nm]])
  if ("umap" %in% names(seu@reductions)) {
    print(DimPlot(seu, reduction = "umap", group.by = "doublet_status") +
            ggtitle(paste0(nm, " - Doublet status")))
  }
  seu
})
names(sample_list_df) <- names(sample_list)

# ---- Remove doublets, keep singlets per sample ----
sample_list_singlets <- lapply(names(sample_list_df), function(nm) {
  seu_df <- sample_list_df[[nm]]
  seu_singlets <- subset(
    seu_df, cells = colnames(seu_df)[seu_df$doublet_status == "Singlet"]
  )
  cat(nm, "| Singlets retained:", ncol(seu_singlets),
      "| Doublets removed:", ncol(seu_df) - ncol(seu_singlets), "\n")
  seu_singlets
})
names(sample_list_singlets) <- names(sample_list_df)

# ---- Save outputs ----
saveRDS(sample_list_df,       "sample_list_doublet_annotated.rds")
saveRDS(sample_list_singlets, "sample_list_singlets.rds")

doublet_calls <- do.call(rbind, lapply(names(sample_list_df), function(nm) {
  seu_df <- sample_list_df[[nm]]
  data.frame(sample = nm, cell = colnames(seu_df),
             doublet_status = seu_df$doublet_status)
}))
