library(Seurat)
library(ggplot2)
library(dplyr)

# ========== PARAMETERS ==========
project_name <- "PBMC"
min_cells <- 3
min_features <- 200
mt_pattern <- "^MT-"
max_feat <- 2500
max_mt <- 5
n_variable <- 2000
n_pcs_compute <- 50
n_pcs <- 20
resolution <- 0.5
seed <- 42

set.seed(seed)

# ========== LOAD AND CREATE SEURAT OBJECTS ==========
# Assume files are: file1.mtx/h5/rds, file2.mtx/h5/rds, file3.mtx/h5/rds in working directory
# Adjust file names and input_type as needed

file_list <- c("sample1", "sample2", "sample3")  # replace with actual file names (without extension)
input_type <- "h5"  # change to "mtx" for MTX folders or "rds" for RDS files

sample_list <- list()

for (i in seq_along(file_list)) {
  if (input_type == "h5") {
    filepath <- paste0(file_list[i], ".h5")
    counts <- Read10X_h5(filename = filepath)
  } else if (input_type == "mtx") {
    filepath <- file_list[i]
    counts <- Read10X(data.dir = filepath)
  } else if (input_type == "rds") {
    filepath <- paste0(file_list[i], ".rds")
    counts <- readRDS(filepath)
    if (!inherits(counts, "Seurat")) {
      seu <- CreateSeuratObject(counts = counts, project = file_list[i],
                                min.cells = min_cells, min.features = min_features)
    } else {
      seu <- counts
    }
    sample_list[[file_list[i]]] <- seu
    next
  }

  seu <- CreateSeuratObject(counts = counts, project = file_list[i],
                            min.cells = min_cells, min.features = min_features)
  seu[["percent.mt"]] <- PercentageFeatureSet(seu, pattern = mt_pattern)

  sample_list[[file_list[i]]] <- seu

  cat("Loaded:", file_list[i], "| Cells:", ncol(seu), "| Genes:", nrow(seu), "\n")
}

# ========== QC METRICS ==========
for (nm in names(sample_list)) {
  sample_list[[nm]][["percent.mt"]] <- PercentageFeatureSet(sample_list[[nm]], pattern = mt_pattern)
}

# Show QC metrics
cat("QC metrics summary before filtering:\n")
for (nm in names(sample_list)) {
  cat("\n", nm, ":\n")
  print(summary(sample_list[[nm]]@meta.data[, c("nFeature_RNA", "nCount_RNA", "percent.mt")]))
}

# ========== FILTER CELLS ==========
sample_list_filtered <- lapply(sample_list, function(seu) {
  n_before <- ncol(seu)
  keep <- seu$nFeature_RNA > min_features &
          seu$nFeature_RNA < max_feat &
          seu$percent.mt < max_mt
  seu_filtered <- subset(seu, cells = colnames(seu)[keep])
  cat("Sample:", seu@project.name, "| Before:", n_before, "| After:", ncol(seu_filtered), "\n")
  return(seu_filtered)
})

# ========== NORMALIZE DATA ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  NormalizeData(seu, normalization.method = "LogNormalize", scale.factor = 10000)
})

# ========== FIND VARIABLE FEATURES ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  FindVariableFeatures(seu, selection.method = "vst", nfeatures = n_variable)
})

# ========== SCALE DATA ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  ScaleData(seu, features = VariableFeatures(seu), verbose = FALSE)
})

# ========== PCA ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  RunPCA(seu, features = VariableFeatures(seu), npcs = n_pcs_compute, verbose = FALSE)
})

# Inspect elbow plot
ElbowPlot(sample_list_filtered[[1]], ndims = n_pcs_compute)

# ========== FIND NEIGHBORS ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  FindNeighbors(seu, dims = 1:n_pcs, reduction = "pca", verbose = FALSE)
})

# ========== CLUSTERING ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  FindClusters(seu, resolution = resolution, algorithm = 1, verbose = FALSE)
})

# ========== UMAP ==========
sample_list_filtered <- lapply(sample_list_filtered, function(seu) {
  RunUMAP(seu, dims = 1:n_pcs, reduction = "pca", verbose = FALSE)
})

# ========== VISUALIZE CLUSTERS ==========
for (nm in names(sample_list_filtered)) {
  p <- DimPlot(sample_list_filtered[[nm]], reduction = "umap", label = TRUE) +
    ggtitle(paste0(nm, " - UMAP (res = ", resolution, ")"))
  print(p)
  cat("Clusters in", nm, ":", paste(table(Idents(sample_list_filtered[[nm]])), collapse = ", "), "\n")
}

# ========== MERGE SAMPLES FOR COMBINED ANALYSIS (OPTIONAL) ==========
seu_merged <- merge(
  sample_list_filtered[[1]],
  y = sample_list_filtered[-1],
  add.cell.ids = names(sample_list_filtered),
  project = project_name
)

cat("\nMerged object:\n")
cat("Total cells:", ncol(seu_merged), "\n")
cat("Total genes:", nrow(seu_merged), "\n")
print(seu_merged)

# Save preprocessed objects
saveRDS(seu_merged, file = "seu_merged_preprocessed.rds")
for (i in seq_along(sample_list_filtered)) {
  saveRDS(sample_list_filtered[[i]], file = paste0(names(sample_list_filtered)[i], "_preprocessed.rds"))
}

cat("\nPreprocessing and clustering complete!\n")
cat("Objects saved: seu_merged_preprocessed.rds and individual sample RDS files\n")
